SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-23_mechanical-scope-e4-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN unified_sites u ON u.id = p.site_id
 WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS NOT DISTINCT FROM p.written::text
                WHEN 'scope_reason' THEN u.scope_reason IS NOT DISTINCT FROM p.written::text
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _scope_plan left behind',
       (to_regclass('pg_temp._scope_plan') IS NOT NULL)::int::text
